import { createRequire } from 'node:module';
const require = createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--enable-webgl', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3000/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing');
const result = await page.evaluate(() => {
  const api = window.__apex, r = api.race, p = r.player;
  r.totalLaps = 4; r.pit.callAfterLaps = 1;
  const s = r.track.samples.at(-1), before = { s: s.s, length: r.track.length, cpCount: r.checkpoints.length };
  p.lapsCompleted = 0; p.cpArmed = true; p.cpNext = 0;
  p.progressDist = s.s; p.sNorm = s.s / r.track.length;
  p.pos = { x: s.x, z: s.z }; p.yaw = Math.atan2(s.tx, s.tz);
  p.vel = { x: s.tx * 25, z: s.tz * 25 }; p.vLong = 25; p.vLat = 0;
  for (let i = 0; i < 10 && r.pit.phase === 'waiting'; i++) api.tick(0.05);
  return { before, laps: p.lapsCompleted, phase: r.pit.phase, callAfterLaps: r.pit.callAfterLaps, progress: p.progressDist, message: document.querySelector('#race-message')?.textContent };
});
console.log(JSON.stringify({ result, errors }, null, 2));
await browser.close();
